{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C36"],
      "claim": "Record C36 reports an absolute oral bioavailability of 46% in healthy volunteers, well above the 20% threshold, supporting a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Record C19 reports probably high absolute oral bioavailability of 80–100% at low doses in fasting healthy volunteers, supporting a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Record C27 reports about 17% availability of ASA in fasting volunteers, below the 20% threshold, arguing against a high prediction; however, other records in this molecule group refer to salicylate/salicylic acid and are inconsistent.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most transferred evidence supports F >= 20%, including direct absolute bioavailability values of 33-100% in healthy volunteers. The only sub-threshold record (ASA ~17%) is weakened by provenance conflict within its molecule group, so high is better supported.",
  "evidence_gaps": [
    "Molecule 3 records mix aspirin, salicylic acid, and sodium salicylate; inconsistent cards were discounted, leaving the sub-threshold ASA record as the only direct parent-drug evidence.",
    "Some records use unspecified bioavailability types or special populations (e.g., CF, malnourished children), adding uncertainty to transfer."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

